public boolean validate()
{
    boolean ret;

    ret = next validate()
        && this.ftdIsFantasyBook();

    return ret;
}

private boolean ftdIsFantasyBook()
{
    SalesTable salesTable = this.dataSource().cursor();

    if (FTDBookTable::findRecId(salesTable.FTDBookTable).Genre != FTDGenreEnum::Fantasy)
    {
        return checkFailed("@ITFormacion:YouMustSelectFantasyBooks");
    }

    return true;
}
